L.Control.SimpleLocate = L.Control.extend({
    options: { position: 'topright', className: 'button-locate' },
    onAdd: function(map) {
        var btn = L.DomUtil.create('button', this.options.className);
        btn.type = 'button';
        btn.title = 'Định vị của tôi';
        btn.innerHTML = '<i class="bi bi-crosshair"></i>';
        var self = this;
        L.DomEvent.on(btn, 'click', function(e) {
            L.DomEvent.stopPropagation(e);
            map.locate({ setView: true, maxZoom: 18 });
            map.once('locationfound', function(ev) {
                if (typeof self.options.afterClick === 'function') {
                    self.options.afterClick({ latlng: ev.latlng });
                }
            });
        });
        return btn;
    }
});